import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.G0y0PQA7.js";const s="/relio/shots/en/preferences-general.png",n="/relio/shots/en/preferences-shortcuts.png",p=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/preferences.md","filePath":"en/features/preferences.md"}'),d={name:"en/features/preferences.md"};function i(l,e,h,c,g,b){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>The pages of Tools › Settings…. Changes are saved immediately and apply to every document.</p><p>Choose a page on the left of the Settings dialog: <strong>General</strong> · <strong>Global groups</strong> · <strong>Translation dictionary</strong> · <strong>Excel template</strong> · <strong>DB connections</strong> · <strong>Shortcuts</strong> · <strong>Password</strong> · <strong>Design check</strong>. Settings are kept on this PC in <code>%APPDATA%\\Relio</code> and remain after you uninstall and reinstall the app.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Display language</td><td><strong>Follow OS language</strong> · 한국어 · English · 日本語 · 中文. New table names, the default environment name and export text also follow this language. 日本語 and 中文 have only part of the text translated; the rest appears in English.</td></tr><tr><td>Theme</td><td>System · Light · Dark · Cherry blossom · Lavender · Everforest · Catppuccin Mocha · Frost. Windows, menus, dialogs and panels follow the theme colors. The canvas is drawn light in the theme&#39;s colors for light themes (Light, Cherry blossom, Lavender, Everforest) and with the default dark canvas for dark themes (Dark, Catppuccin Mocha, Frost); nodes such as tables share the same colors among light themes and among dark themes. Exports and printing always use light colors. On Windows 11, Cherry blossom, Lavender, Everforest, Catppuccin Mocha and Frost also color the window title bar.</td></tr><tr><td>Canvas colors</td><td><strong>Theme</strong> · <strong>Light</strong>. Light keeps the canvas light even with a dark theme. Colors set on nodes are adjusted in brightness on screen only; the values in the file stay the same.</td></tr><tr><td>Toolbar</td><td><strong>Relio default</strong> · <strong>ERMaster style (everything, as before)</strong>. ERMaster style shows every original toolbar button and the original right-click menus. The menu bar is the same.</td></tr></tbody></table><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Automatic backup interval (minutes)</td><td>Unsaved changes are backed up at this interval (5 by default); 0 turns it off. Up to 10 recent backups per file are kept in the <code>backup</code> folder of the settings folder.</td></tr><tr><td>Reopen last session&#39;s documents at startup</td><td>Reopens the files that were open when you quit.</td></tr><tr><td>Save in Git-friendly order</td><td>On by default. <a href="/relio/en/features/file#sorted-saving">File › Sorted saving</a></td></tr></tbody></table><h3 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h3><p><strong>Check for new versions automatically (once a day)</strong> — When on, Relio fetches only version information from the public releases page once a day. The result of the last check is shown below it (&quot;Last checked: … — Up to date&quot;). <a href="/relio/en/features/update">Updates</a></p><h3 id="ai-tools" tabindex="-1">AI tools <a class="header-anchor" href="#ai-tools" aria-label="Permalink to &quot;AI tools&quot;">​</a></h3><p><strong>AI changes</strong> — <strong>Apply right away (default)</strong> · <strong>Review first</strong>. Apply right away puts AI changes straight into the open document if they do not overlap your unsaved edits (not saved, undoable); if they overlap or you are editing, you pick in a merge tab. Review first always opens a merge tab. <a href="/relio/en/features/ai#review-first-and-the-merge-tab">Working with AI › Review first and the merge tab</a></p><h3 id="remembered-per-file-on-this-pc" tabindex="-1">Remembered per file on this PC <a class="header-anchor" href="#remembered-per-file-on-this-pc" aria-label="Permalink to &quot;Remembered per file on this PC&quot;">​</a></h3><p>For each file, Relio remembers on this PC the target database version, the DB connection and the password storage method (as well as design check ignores, text export settings and so on). The table shows the file, target and connection; <strong>Delete</strong> removes one row, and <strong>Delete records of missing files</strong> cleans up records of files that no longer exist. If you move a file elsewhere, its record starts fresh.</p><h3 id="highlight" tabindex="-1">Highlight <a class="header-anchor" href="#highlight" aria-label="Permalink to &quot;Highlight&quot;">​</a></h3><p>Hover and selection connection highlights, dimming the rest, dim level, highlight effect and reduce motion. <a href="/relio/en/features/find#highlight-settings">Find and highlight › Highlight settings</a></p><h3 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h3><p><strong>Keep a diagnostic log</strong> — Keeps diagnostic information such as errors and start-up time only in the settings folder on this PC (last 7 days). It is never sent over the internet and contains no file contents, names or paths. When off, no new log is written. <strong>Delete diagnostic log</strong> removes what has been kept so far. <a href="/relio/en/features/troubleshooting#diagnostic-log">Help and troubleshooting › Diagnostic log</a></p><figure class="shot" data-scene="preferences-general"><img src="'+s+'" alt="Settings › General — the Display and Highlight groups" loading="lazy"><figcaption>Settings › General — the Display and Highlight groups</figcaption></figure><h2 id="global-groups" tabindex="-1">Global groups <a class="header-anchor" href="#global-groups" aria-label="Permalink to &quot;Global groups&quot;">​</a></h2><p>Global groups are column groups shared by several files. They are stored in this PC&#39;s app settings and copied into a document with <strong>Add to document</strong>. This page shows the list (group name and number of columns); edit them with <strong>Manage global groups…</strong>. <a href="/relio/en/features/model#manage-groups-and-global-groups">Model menu › Manage groups</a></p><h2 id="translation-dictionary" tabindex="-1">Translation dictionary <a class="header-anchor" href="#translation-dictionary" aria-label="Permalink to &quot;Translation dictionary&quot;">​</a></h2><p>The list of dictionaries used to fill logical names from physical names when importing from a database.</p><ul><li>A translation dictionary file is a UTF-8 text file with one source word and its translation per line, separated by a comma (for example <code>customer,Customer</code>). Lines without a comma are skipped.</li><li>The table shows Name · Entries · File location. The built-in dictionary included in the app is always at the top.</li><li><strong>New…</strong> · <strong>Add (file)…</strong> · <strong>Remove</strong> (only removes it from the list; the file is not deleted) · <strong>Up</strong> · <strong>Down</strong> · <strong>Open file</strong>.</li><li>Dictionaries higher in the list are used first. Choose the dictionaries for each document in Model › Translation management….</li></ul><h2 id="excel-template" tabindex="-1">Excel template <a class="header-anchor" href="#excel-template" aria-label="Permalink to &quot;Excel template&quot;">​</a></h2><ul><li><strong>Built-in templates</strong> — Templates included in the app (Korean — table specification and others). Use <strong>Save to file…</strong> to customize one, then <strong>Add as user template</strong>.</li><li><strong>User templates</strong> — These also appear in the template list of the Excel export. They are <code>.xlsx</code> or <code>.xls</code> files with words and loops sheets and template sheets. <strong>Add…</strong> · <strong>Remove</strong>.</li></ul><p><a href="/relio/en/features/export#excel">Export › Excel</a></p><h2 id="db-connections" tabindex="-1">DB connections <a class="header-anchor" href="#db-connections" aria-label="Permalink to &quot;DB connections&quot;">​</a></h2><ul><li><strong>Saved connections</strong> — Name · Location · User of the connections saved from the database connection dialog. <strong>Rename</strong> · delete. Passwords are not stored here.</li><li><strong>DB clients</strong> — <strong>Oracle Instant Client folder</strong> (the full path of the folder with <code>oci.dll</code>; no network paths; if empty, PATH is searched; restart the app for a change to take effect), and an <strong>ODBC driver</strong> for each of Db2, Informix and MS Access (a driver name or the full path of a <code>.dll</code>; empty = default name). For security, only the driver files and Oracle folder registered here are used.</li><li>Save with <strong>Save client settings</strong>.</li></ul><p><a href="/relio/en/features/database">Databases</a></p><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h2><p>View and change every shortcut in a table (Section · Action · Key). Help › Keyboard shortcuts… also opens this page.</p><ul><li>Click <strong>Change</strong> and then press the new key (<kbd>Esc</kbd> = cancel). The new shortcut shows in the menus right away.</li><li><strong>Reset</strong> resets that row, and <strong>Clear</strong> removes its key. <strong>Reset all to defaults</strong> resets everything.</li><li>Keys already used by another action are flagged with &quot;Conflicts: …&quot;.</li><li>The arrow keys (move by 1) · <kbd>Shift</kbd>+arrow keys (move by 10) · <kbd>Tab</kbd> (next node) · <kbd>Space</kbd> (hold and drag to pan) · <kbd>Ctrl</kbd>+mouse wheel (zoom) are <strong>Fixed</strong> keys that cannot be changed.</li></ul><h3 id="default-shortcuts" tabindex="-1">Default shortcuts <a class="header-anchor" href="#default-shortcuts" aria-label="Permalink to &quot;Default shortcuts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Action</th><th>Key</th></tr></thead><tbody><tr><td>File</td><td>New diagram / Open / Save / Save as</td><td><kbd>Ctrl</kbd>+<kbd>N</kbd> / <kbd>Ctrl</kbd>+<kbd>O</kbd> / <kbd>Ctrl</kbd>+<kbd>S</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>S</kbd></td></tr><tr><td>File</td><td>Close / Print</td><td><kbd>Ctrl</kbd>+<kbd>W</kbd> / <kbd>Ctrl</kbd>+<kbd>P</kbd></td></tr><tr><td>Edit</td><td>Undo / Redo</td><td><kbd>Ctrl</kbd>+<kbd>Z</kbd> / <kbd>Ctrl</kbd>+<kbd>Y</kbd> (or <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd>)</td></tr><tr><td>Edit</td><td>Cut / Copy / Paste / Delete / Select all</td><td><kbd>Ctrl</kbd>+<kbd>X</kbd> / <kbd>Ctrl</kbd>+<kbd>C</kbd> / <kbd>Ctrl</kbd>+<kbd>V</kbd> / <kbd>Delete</kbd> / <kbd>Ctrl</kbd>+<kbd>A</kbd></td></tr><tr><td>Edit</td><td>Find bar / Change find bar match mode / Find and replace</td><td><kbd>Ctrl</kbd>+<kbd>F</kbd> / <kbd>Alt</kbd>+<kbd>W</kbd> / <kbd>Ctrl</kbd>+<kbd>H</kbd></td></tr><tr><td>Edit</td><td>Rename in place / Open properties / Cancel tool or clear selection</td><td><kbd>F2</kbd> / <kbd>Enter</kbd> / <kbd>Esc</kbd></td></tr><tr><td>View</td><td>Zoom in / Zoom out / 100%</td><td><kbd>Ctrl</kbd>+<kbd>=</kbd> / <kbd>Ctrl</kbd>+<kbd>-</kbd> / <kbd>Ctrl</kbd>+<kbd>0</kbd></td></tr><tr><td>View</td><td>Collapse or expand right panel / bottom panel / Maximize canvas</td><td><kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>B</kbd> / <kbd>Ctrl</kbd>+<kbd>J</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>M</kbd></td></tr><tr><td>View</td><td>Next document tab / Previous document tab</td><td><kbd>Ctrl</kbd>+<kbd>Tab</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Tab</kbd></td></tr><tr><td>View</td><td>Compare: switch grouping</td><td><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>G</kbd></td></tr><tr><td>Tools</td><td>Select tool / Hand tool / Table / View / 1:N relationship / Note / Category</td><td><kbd>V</kbd> / <kbd>H</kbd> / <kbd>T</kbd> / <kbd>W</kbd> / <kbd>R</kbd> / <kbd>N</kbd> / <kbd>C</kbd></td></tr><tr><td>Help</td><td>User guide</td><td><kbd>F1</kbd></td></tr></tbody></table><p>There are also <kbd>F3</kbd> · <kbd>Shift</kbd>+<kbd>F3</kbd> (find results), <kbd>F8</kbd> · <kbd>Shift</kbd>+<kbd>F8</kbd> (design check findings and merge conflicts), and <kbd>1</kbd> · <kbd>2</kbd> · <kbd>3</kbd> · <kbd>Ctrl</kbd>+<kbd>Enter</kbd> in the merge view.</p><figure class="shot" data-scene="preferences-shortcuts"><img src="'+n+'" alt="Settings › Shortcuts — keys per action, with the Change, Reset and Clear buttons" loading="lazy"><figcaption>Settings › Shortcuts — keys per action, with the Change, Reset and Clear buttons</figcaption></figure><h2 id="password" tabindex="-1">Password <a class="header-anchor" href="#password" aria-label="Permalink to &quot;Password&quot;">​</a></h2><p>The list of database passwords saved with <strong>Remember password</strong> in the connection dialog. The passwords live in the Windows Credential Manager; here you can only see the list and delete entries. <a href="/relio/en/features/database#how-passwords-are-stored">Databases › How passwords are stored</a></p><h2 id="design-check" tabindex="-1">Design check <a class="header-anchor" href="#design-check" aria-label="Permalink to &quot;Design check&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Show on the canvas</td><td>Error and warning marks on the canvas (same as View › Show design check marks).</td></tr><tr><td>Show info marks on canvas</td><td>Also draws info findings on the canvas.</td></tr><tr><td>Suggestions while typing</td><td>The candidate list in the column properties dialog.</td></tr><tr><td>Relationship name pairs (highlight candidates, prefill, notice after 1:N)</td><td>Candidate highlighting with the relationship tool and the notice about same-name columns.</td></tr><tr><td>Rule table</td><td>For each rule, change the <strong>On</strong> checkbox and the <strong>Severity</strong>. <strong>Restore defaults</strong> resets them.</td></tr></tbody></table><p>Ignores on this PC exist only in the per-file records and are not shared with your team. <a href="/relio/en/features/check">Design check and suggestions</a></p>',42)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
